import { types } from "node:util";
import * as inner from "./inner.js";
import * as again from "./inner.js";
import { sameAsMine } from "./other.js";
import * as toolbox from "./tools.js";
export * as tools from "./tools.js";
export { setMid } from "./inner.js";

export function describe() {
  const d = Object.getOwnPropertyDescriptor(inner, "alpha");
  return [
    `keys=${Object.keys(inner).join(",")}`,
    `tag=${Object.prototype.toString.call(inner)}`,
    `same=${inner === again}`,
    `across=${sameAsMine(inner)}`,
    `namespace=${types.isModuleNamespaceObject(inner)}`,
    `descriptor=${d.value},${d.writable},${d.enumerable},${d.configurable}`,
    `frozen=${Object.isFrozen(inner)},sealed=${Object.isSealed(inner)}`,
    `proto=${Object.getPrototypeOf(inner)}`,
    `mid=${inner.mid}`,
  ].join(" ");
}
export function assign() {
  try {
    inner.alpha = 5;
    return "assigned";
  } catch (error) {
    return `${error.name}: ${error.message}`;
  }
}
export function toolKeys() {
  return Object.keys(toolbox).join(",");
}
